// CesiumViewer.jsx
import React, { useEffect, useRef, useState } from "react";

// CDN (or /cesium/Cesium.js if you host locally in public/cesium)
const CESIUM_CDN = "https://cesium.com/downloads/cesiumjs/releases/1.104/Build/Cesium/Cesium.js";

// If you have a Cesium Ion token, put it here or set it via environment and inject it.
// const ION_TOKEN = process.env.REACT_APP_CESIUM_ION_TOKEN || "";
const ION_TOKEN = ""; // <-- set your token string here (or leave empty to use fallback)

// Example local KMZ served from public/uploaded_map
const LOCAL_KMZ = "/uploaded_map/paths.kmz";

function loadScript(src) {
  return new Promise((resolve, reject) => {
    if (window.Cesium) return resolve(window.Cesium);
    const existing = Array.from(document.scripts).find(s => s.src && s.src.includes("Cesium.js"));
    if (existing) {
      existing.addEventListener("load", () => resolve(window.Cesium));
      existing.addEventListener("error", reject);
      return;
    }
    const s = document.createElement("script");
    s.src = src;
    s.async = true;
    s.onload = () => resolve(window.Cesium);
    s.onerror = (e) => reject(e);
    document.head.appendChild(s);
  });
}

export default function CesiumViewer() {
  const containerRef = useRef(null);
  const viewerRef = useRef(null);
  const [status, setStatus] = useState("init");

  useEffect(() => {
    let mounted = true;
    let viewer;

    async function init() {
      try {
        setStatus("loading-script");
        await loadScript(CESIUM_CDN);

        if (!window.Cesium) {
          console.error("Cesium not present after script load.");
          setStatus("error");
          return;
        }

        // Set Ion token if available
        if (ION_TOKEN) {
          try {
            window.Cesium.Ion.defaultAccessToken = ION_TOKEN;
          } catch (e) {
            console.warn("Failed to set Ion token:", e);
          }
        }

        // Choose terrain provider based on token validity / presence
        // If you leave ION_TOKEN blank you'll use EllipsoidTerrainProvider (no Ion calls)
        let terrainProvider;
        if (ION_TOKEN) {
          try {
            // best-effort: attempt to create world terrain
            terrainProvider = window.Cesium.createWorldTerrain();
          } catch (e) {
            console.warn("createWorldTerrain failed, falling back to ellipsoid.", e);
            terrainProvider = new window.Cesium.EllipsoidTerrainProvider();
          }
        } else {
          terrainProvider = new window.Cesium.EllipsoidTerrainProvider();
        }

        setStatus("creating-viewer");
        viewer = new window.Cesium.Viewer(containerRef.current, {
          terrainProvider,
          timeline: false,
          animation: false,
          baseLayerPicker: true,
          infoBox: true,
          sceneModePicker: true
        });

        viewerRef.current = viewer;
        if (!mounted) return;

        setStatus("viewer-ready");
        // Now viewer exists — safe to add data sources, primitives, entities
        // Example: load a local KMZ (same origin); ensure URL path exists
        try {
          const kmzUrl = LOCAL_KMZ; // example
          // Use KmlDataSource.load with clampToGround option false if you want outlines to show
          const ds = await window.Cesium.KmlDataSource.load(kmzUrl, {
            camera: viewer.scene.camera,
            canvas: viewer.scene.canvas,
            clampToGround: false // set false to allow outlines (but may float above terrain)
          });
          viewer.dataSources.add(ds); // safe because viewer is ready
          viewer.zoomTo(ds).catch(() => {});
        } catch (err) {
          console.warn("KMZ load failed (check URL & CORS):", err);
        }
      } catch (err) {
        console.error("Initialization error:", err);
        setStatus("error");
      }
    }

    init();

    return () => {
      mounted = false;
      if (viewerRef.current) {
        try {
          viewerRef.current.destroy();
        } catch (e) { /* ignore */ }
      }
    };
  }, []);

  return (
    <div style={{ display: "flex", height: "100vh" }}>
      <div style={{ width: 320, padding: 12, background: "#0f1720", color: "#e6eef6" }}>
        <h3>Cesium Viewer</h3>
        <div>Status: {status}</div>
        <div style={{ marginTop: 8 }}>
          <div className="small">Ion token:</div>
          <div style={{ fontSize: 12, color: ION_TOKEN ? "lightgreen" : "orange" }}>
            {ION_TOKEN ? "Using provided Ion token" : "No Ion token — using EllipsoidTerrainProvider"}
          </div>
        </div>
        <hr />
        <div className="small">Local KMZ path used for demo:</div>
        <code style={{ fontSize: 12, wordBreak: "break-all" }}>{LOCAL_KMZ}</code>
      </div>

      <div ref={containerRef} id="cesiumContainer" style={{ flex: 1 }} />
    </div>
  );
}
